#!/usr/bin/env python3
"""CSV Insights - a dependency-free command-line analytics tool.

Parses RFC-4180-style CSV files, supports filtering, grouping, and
numeric aggregation (sum/avg) with Decimal precision. Outputs JSON or CSV.
"""

import sys
import csv
import json
import argparse
from decimal import Decimal, InvalidOperation


class CsvInsightError(Exception):
    """Base class for all errors that should exit non-zero with a message."""


def read_csv(path):
    """Read an RFC-4180-style CSV file using the stdlib csv module.

    Returns (headers, rows) where headers is a list of column names and
    rows is a list of lists of string values.
    """
    try:
        f = open(path, "r", newline="", encoding="utf-8")
    except OSError as exc:
        raise CsvInsightError(f"cannot open input file {path!r}: {exc}")

    with f:
        reader = csv.reader(f)
        try:
            headers = next(reader)
        except StopIteration:
            raise CsvInsightError("input file is empty (no header row)")

        if not headers:
            raise CsvInsightError("header row is empty")
        if len(headers) != len(set(headers)):
            seen = set()
            dup = None
            for h in headers:
                if h in seen:
                    dup = h
                    break
                seen.add(h)
            raise CsvInsightError(f"duplicate header column: {dup!r}")

        rows = []
        ncols = len(headers)
        for lineno, fields in enumerate(reader, start=2):
            if len(fields) != ncols:
                raise CsvInsightError(
                    f"line {lineno}: expected {ncols} fields, got {len(fields)}"
                )
            rows.append(fields)

    return headers, rows


def parse_where(filters, headers):
    """Parse --where COLUMN=VALUE filters into a list of (col_index, value).

    Multiple filters combine with AND and compare exact strings.
    """
    header_index = {h: i for i, h in enumerate(headers)}
    parsed = []
    for spec in filters:
        if "=" not in spec:
            raise CsvInsightError(
                f"malformed filter {spec!r}: expected COLUMN=VALUE"
            )
        col, _, value = spec.partition("=")
        if col == "":
            raise CsvInsightError(
                f"malformed filter {spec!r}: empty column name"
            )
        if col not in header_index:
            raise CsvInsightError(f"unknown column in filter: {col!r}")
        parsed.append((header_index[col], value))
    return parsed


def apply_filters(rows, parsed_filters):
    """Return rows that match all filters (exact string comparison)."""
    result = []
    for row in rows:
        keep = True
        for idx, value in parsed_filters:
            if row[idx] != value:
                keep = False
                break
        if keep:
            result.append(row)
    return result


def to_decimal(value, row_num, col_name):
    """Convert a string cell to Decimal, raising on blank/invalid."""
    if value == "" or value is None:
        raise CsvInsightError(
            f"row {row_num}, column {col_name!r}: blank numeric value"
        )
    try:
        return Decimal(value)
    except (InvalidOperation, ValueError):
        raise CsvInsightError(
            f"row {row_num}, column {col_name!r}: invalid numeric value {value!r}"
        )


def decimal_to_str(d):
    """Render a Decimal as a plain, minimal decimal string."""
    # Normalize to strip trailing zeros, but avoid scientific notation.
    normalized = d.normalize()
    sign, digits, exponent = normalized.as_tuple()
    if exponent > 0:
        # Integer with trailing zeros stripped by normalize; reattach.
        s = format(normalized, "f")
    else:
        s = format(normalized, "f")
    # Decimal.normalize() can produce strings like "1E+2"; format with "f"
    # avoids that. But normalize on "100" gives "1E+2"; format "f" -> "100".
    if "E" in s or "e" in s:
        s = format(normalized, "f")
    # Avoid "-0"
    if s == "-0":
        s = "0"
    return s


def aggregate(headers, rows, group_by_col, sum_cols, avg_cols):
    """Group rows by group_by_col and compute sum/avg for given columns.

    Returns (out_headers, out_rows) where out_rows are lists of strings.
    """
    header_index = {h: i for i, h in enumerate(headers)}
    if group_by_col not in header_index:
        raise CsvInsightError(f"unknown column in --group-by: {group_by_col!r}")
    gb_idx = header_index[group_by_col]

    sum_idx = []
    for c in sum_cols:
        if c not in header_index:
            raise CsvInsightError(f"unknown column in --sum: {c!r}")
        sum_idx.append((c, header_index[c]))

    avg_idx = []
    for c in avg_cols:
        if c not in header_index:
            raise CsvInsightError(f"unknown column in --avg: {c!r}")
        avg_idx.append((c, header_index[c]))

    # Build groups preserving first-seen order, but we'll sort lexicographically.
    groups = {}  # group_value -> {"sums": {col: Decimal}, "avgs": {col: [Decimal,...]}, "count": int}
    for rnum, row in enumerate(rows, start=1):
        gval = row[gb_idx]
        if gval not in groups:
            groups[gval] = {
                "sums": {c: Decimal(0) for c, _ in sum_idx},
                "avgs": {c: [] for c, _ in avg_idx},
                "count": 0,
            }
        g = groups[gval]
        g["count"] += 1
        for c, ci in sum_idx:
            g["sums"][c] += to_decimal(row[ci], rnum, c)
        for c, ci in avg_idx:
            g["avgs"][c].append(to_decimal(row[ci], rnum, c))

    out_headers = [group_by_col]
    for c, _ in sum_idx:
        out_headers.append(f"sum_{c}")
    for c, _ in avg_idx:
        out_headers.append(f"avg_{c}")

    out_rows = []
    for gval in sorted(groups.keys()):
        g = groups[gval]
        out = [gval]
        for c, _ in sum_idx:
            out.append(decimal_to_str(g["sums"][c]))
        for c, _ in avg_idx:
            vals = g["avgs"][c]
            total = sum(vals, Decimal(0))
            avg = total / Decimal(len(vals))
            out.append(decimal_to_str(avg))
        out_rows.append(out)

    return out_headers, out_rows


def output_json(headers, rows):
    out = []
    for row in rows:
        obj = {}
        for h, v in zip(headers, row):
            obj[h] = v
        out.append(obj)
    return json.dumps(out, indent=2, ensure_ascii=False)


def output_csv(headers, rows):
    import io

    buf = io.StringIO()
    writer = csv.writer(buf, quoting=csv.QUOTE_MINIMAL, lineterminator="\r\n")
    writer.writerow(headers)
    for row in rows:
        writer.writerow(row)
    return buf.getvalue()


def build_parser():
    p = argparse.ArgumentParser(
        prog="csv-insights",
        description="Dependency-free CSV analytics tool.",
    )
    p.add_argument("input", help="input CSV file path")
    p.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="filter rows (exact match); may be repeated (AND)",
    )
    p.add_argument(
        "--group-by",
        dest="group_by",
        metavar="COLUMN",
        default=None,
        help="group rows by column value",
    )
    p.add_argument("--sum", action="append", default=[], metavar="COLUMN")
    p.add_argument("--avg", action="append", default=[], metavar="COLUMN")
    p.add_argument(
        "--output",
        choices=["json", "csv"],
        default="json",
        help="output format (default: json)",
    )
    return p


def main(argv=None):
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as e:
        # argparse exits with code 2 on error; preserve that.
        raise

    try:
        headers, rows = read_csv(args.input)
        parsed_filters = parse_where(args.where, headers)
        filtered = apply_filters(rows, parsed_filters)

        if args.sum or args.avg:
            if args.group_by is None:
                raise CsvInsightError(
                    "--sum/--avg require --group-by"
                )
            out_headers, out_rows = aggregate(
                headers, filtered, args.group_by, args.sum, args.avg
            )
        else:
            if args.group_by is not None:
                raise CsvInsightError(
                    "--group-by provided without --sum or --avg"
                )
            out_headers = headers
            out_rows = filtered

        if args.output == "json":
            sys.stdout.write(output_json(out_headers, out_rows))
            sys.stdout.write("\n")
        else:
            sys.stdout.write(output_csv(out_headers, out_rows))
    except CsvInsightError as e:
        sys.stderr.write(f"error: {e}\n")
        return 1
    except BrokenPipeError:
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

